mapper.select:
SELECT m.id, m.alert_id AS alertId, m.animal_cage_id AS animalCageId, m.status_code AS statusCode, m.fired_at AS firedAt, m.read_at AS readAt, m.read_by AS readBy, cci.shelve_id AS shelveId, cci.position_x AS positionX, cci.position_y AS positionY, si.room_id AS roomId, si.room_name AS roomName, si.shelve_name AS shelveName, si.campus_name AS campusName, si.floor_name AS floorName, d.project_pi_name AS projectPiName, d.experimenter_name AS experimenterName, d.cage_type_code AS cageTypeCode, d.cage_box_code AS cageBoxCode, d.aup_number AS aupNumber FROM cage_vet_message m LEFT JOIN cage_cell_index cci ON cci.animal_cage_id = m.animal_cage_id LEFT JOIN cage_shelf_index si ON si.id = cci.shelf_index_id LEFT JOIN cage_cell_detail d ON d.animal_cage_id = m.animal_cage_id
WHERE m.animal_cage_id IN #{cid}
ORDER BY m.fired_at DESC, m.id DESC
